import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as projectService from "@/server/services/project-service";
import * as projectRepo from "@/server/repositories/project-repository";
import * as pm from "@/server/repositories/project-member-repository";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("private", () => {
  it("works", async () => {
    const t = await createTenant("priv");
    const priv = await projectRepo.insertProject({ orgId: t.org.id, name: "Secret", slug: "secret", key: "SEC", description: null, visibility: "private", leadId: t.userIds.admin, color: "#6366f1", targetDate: null });
    const issue = await issueService.createIssue(t.actors.admin, issueInput(t.org.id, priv.id, { title: "secret issue" }));
    const orgIssue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "open issue" }));
    const c = await commentService.createComment(t.actors.admin, { orgId: t.org.id, issueId: issue.id, body: "hi", parentId: null, mentionedUserIds: [] } as never);

    const m = t.actors.member;
    expect(await projectService.canViewProject(m, priv)).toBe(false);
    expect(await projectService.canViewProject(t.actors.admin, priv)).toBe(true);
    expect(await projectService.canViewProject(t.actors.owner, priv)).toBe(true);
    expect(await projectService.canViewProject({ ...m, isPlatformStaff: true }, priv)).toBe(true);
    expect(await projectService.canViewProject(m, t.project)).toBe(true);

    await expect(projectService.getProject(m, t.org.id, "secret")).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.getIssue(m, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.getBoard(m, t.org.id, priv.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.getThread(m, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.createIssue(m, issueInput(t.org.id, priv.id))).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.updateIssue(m, { orgId: t.org.id, issueId: issue.id, title: "hacked" })).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.moveIssue(m, { orgId: t.org.id, issueId: issue.id, toStatus: "done", toIndex: 0 })).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.updateComment(m, { orgId: t.org.id, commentId: c.id, body: "x" } as never)).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.deleteComment(t.actors.viewer, { orgId: t.org.id, commentId: c.id } as never)).rejects.toBeInstanceOf(NotFoundError);
    await expect(projectService.updateProject(m, { orgId: t.org.id, projectId: priv.id, name: "zz" })).rejects.toBeInstanceOf(NotFoundError);
    await expect(projectService.restoreProject(m, t.org.id, priv.id)).rejects.toBeInstanceOf(NotFoundError);

    const lp = await projectService.listProjects(m, { orgId: t.org.id, limit: 25, cursor: null } as never);
    expect(lp.total).toBe(1);
    expect(lp.items.map((x) => x.project.id)).toEqual([t.project.id]);
    const li = await issueService.listIssues(m, { orgId: t.org.id, limit: 25, cursor: null } as never);
    expect(li.total).toBe(1);
    expect(li.items.map((x) => x.id)).toEqual([orgIssue.id]);
    const la = await issueService.listIssues(t.actors.admin, { orgId: t.org.id, limit: 25, cursor: null } as never);
    expect(la.total).toBe(2);

    await pm.addProjectMember(t.org.id, priv.id, m.userId);
    expect(await projectService.canViewProject(m, priv)).toBe(true);
    expect((await projectService.listProjects(m, { orgId: t.org.id, limit: 25, cursor: null } as never)).total).toBe(2);
    expect((await issueService.listIssues(m, { orgId: t.org.id, limit: 25, cursor: null } as never)).total).toBe(2);
    await issueService.getIssue(m, t.org.id, issue.id);
    await pm.removeProjectMember(t.org.id, priv.id, m.userId);
    await expect(issueService.getIssue(m, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);

    await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: priv.id, leadId: m.userId });
    await issueService.getIssue(m, t.org.id, issue.id);
    expect((await issueService.listIssues(m, { orgId: t.org.id, limit: 25, cursor: null } as never)).total).toBe(2);
  });
});
EOF
